pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(0));
        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();
        assertTrue(c.pot() == 10);
    }
